css:
.stress-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #eaf4fb 0%, #d6ecf7 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #17324d;
}
.stress-sim-header {
    background: linear-gradient(135deg, #0d3b66, #2a7fb8);
    color: #ffffff;
    border-radius: 20px;
    padding: 32px;
    text-align: center;
    margin-bottom: 28px;
    box-shadow: 0 14px 36px rgba(13,59,102,0.25);
}
.stress-sim-header h1 {
    margin: 0;
    font-size: 1.8rem;
    font-weight: 700;
    letter-spacing: 0.02em;
}
.stress-sim-subtitle {
    margin: 8px 0 0;
    opacity: 0.9;
    font-size: 0.95rem;
}
.stress-sim-period-counter {
    background: #ffffff;
    border-radius: 14px;
    padding: 14px 22px;
    margin-bottom: 22px;
    font-weight: 600;
    box-shadow: 0 4px 14px rgba(0,0,0,0.06);
    display: flex;
    align-items: center;
    gap: 10px;
}
.stress-sim-phase {
    margin-left: auto;
    font-size: 0.85rem;
    background: #0d3b66;
    color: #fff;
    padding: 4px 12px;
    border-radius: 999px;
}
.stress-sim-briefing {
    background: #ffffff;
    border-left: 5px solid #e63946;
    border-radius: 12px;
    padding: 18px 22px;
    margin-bottom: 22px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.05);
}
.stress-sim-briefing h3 {
    margin: 0 0 8px;
    color: #0d3b66;
    font-size: 1.05rem;
}
.stress-sim-briefing p {
    margin: 0;
    line-height: 1.5;
    color: #30485c;
}
.stress-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 26px;
}
.stress-sim-status-card {
    background: #ffffff;
    border-radius: 16px;
    padding: 20px;
    border-top: 4px solid #2a7fb8;
    box-shadow: 0 6px 18px rgba(13,59,102,0.08);
    transition: transform 0.2s ease;
}
.stress-sim-status-card:hover { transform: translateY(-2px); }
.stress-sim-status-card.pulse { border-top-color: #e63946; }
.stress-sim-label {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #6b8299;
    margin-bottom: 8px;
}
.stress-sim-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #0d3b66;
}
.stress-sim-controls {
    background: #ffffff;
    border-radius: 18px;
    padding: 24px;
    margin-bottom: 26px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.06);
}
.stress-sim-controls h3 {
    margin: 0 0 16px;
    color: #0d3b66;
}
.stress-sim-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
    margin-bottom: 18px;
}
.stress-sim-field label {
    display: block;
    font-size: 0.82rem;
    font-weight: 600;
    color: #30485c;
    margin-bottom: 6px;
}
.stress-sim-controls input,
.stress-sim-controls select {
    background: #f5f9fc;
    border: 1px solid #b8d2e3;
    color: #0d3b66;
    border-radius: 8px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.95rem;
}
.stress-sim-controls select option {
    background: #ffffff;
    color: #0d3b66;
}
.stress-sim-buttons {
    display: flex;
    gap: 10px;
    align-items: center;
}
.stress-sim-controls .btn-primary {
    background: #0d3b66;
    border-color: #0d3b66;
    padding: 10px 24px;
    font-weight: 600;
    border-radius: 8px;
}
.stress-sim-controls .btn-primary:hover {
    background: #2a7fb8;
    border-color: #2a7fb8;
}
.stress-sim-hint {
    background: #fff8e6;
    border-left: 4px solid #f4a261;
    padding: 12px 18px;
    border-radius: 10px;
    margin-bottom: 22px;
    color: #704200;
    font-size: 0.92rem;
    min-height: 18px;
}
.stress-sim-hint:empty { display: none; }
.stress-sim-history {
    background: #ffffff;
    border-radius: 16px;
    padding: 22px;
    margin-bottom: 26px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.06);
}
.stress-sim-history h3 {
    color: #0d3b66;
    margin-top: 0;
    font-size: 1.05rem;
}
.stress-sim-history table {
    width: 100%;
    color: #17324d;
}
.stress-sim-history th {
    background: #eaf4fb;
    color: #0d3b66;
    font-size: 0.82rem;
}
.stress-sim-chart {
    background: #ffffff;
    border-radius: 16px;
    padding: 22px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.06);
    height: 420px;
}
.stress-sim-chart h3 {
    color: #0d3b66;
    margin-top: 0;
    font-size: 1.05rem;
}
@media (max-width: 768px) {
    .stress-sim-container { padding: 14px; }
    .stress-sim-header { padding: 22px; }
    .stress-sim-header h1 { font-size: 1.4rem; }
    .stress-sim-value { font-size: 1.5rem; }
}

